UPDATE tools SET command_template='nmap {target} {scan_type} {port_range} {top_ports} {os_detection} {service_version} {script_scan} {aggressive} {timing} {verbose} {no_dns}', parameters='{"form": [{"name": "target", "label": "Target", "type": "text", "required": true, "default": "", "placeholder": "scanme.nmap.org", "description": "Target IP, hostname or CIDR"}, {"name": "scan_type", "label": "Scan Type", "type": "select", "required": false, "default": "-sS", "placeholder": "", "options": ["-sS (SYN)", "-sT (Connect)", "-sU (UDP)", "-sA (ACK)", "-sN (NULL)"], "secret": true}, {"name": "port_range", "label": "Port Range", "type": "text", "required": false, "default": "", "placeholder": "-p 22,80,443 or -p 1-1000", "description": "Ports to scan"}, {"name": "top_ports", "label": "Top Ports", "type": "text", "required": false, "default": "", "placeholder": "--top-ports 1000", "description": "Scan most common ports"}, {"name": "os_detection", "label": "OS Detection", "type": "text", "required": false, "default": "", "placeholder": "-O", "description": "Enable OS detection (flag value)"}, {"name": "service_version", "label": "Service Version", "type": "text", "required": false, "default": "", "placeholder": "-sV", "description": "Probe for service versions (flag value)"}, {"name": "script_scan", "label": "Script Scan", "type": "text", "required": false, "default": "", "placeholder": "-sC", "description": "Run default NSE scripts (flag value)"}, {"name": "aggressive", "label": "Aggressive", "type": "text", "required": false, "default": "", "placeholder": "-A", "description": "OS+Version+Scripts+Traceroute (flag value)"}, {"name": "timing", "label": "Timing", "type": "select", "required": false, "default": "-T3", "placeholder": "", "options": ["-T0 (Paranoid)", "-T1 (Sneaky)", "-T2 (Polite)", "-T3 (Normal)", "-T4 (Aggressive)", "-T5 (Insane)"]}, {"name": "verbose", "label": "Verbose", "type": "text", "required": false, "default": "", "placeholder": "-v", "description": "Increase verbosity (flag value)"}, {"name": "no_dns", "label": "No DNS", "type": "text", "required": false, "default": "", "placeholder": "-n", "description": "Never do DNS resolution (flag value)"}], "danger_level": "low", "target_types": []}'::jsonb WHERE name='nmap' AND is_active=TRUE;
UPDATE tools SET command_template='masscan {target} {ports} {rate} {banners} {output}', parameters='{"form": [{"name": "target", "label": "Target", "type": "text", "required": true, "default": "", "placeholder": "192.168.1.0/24", "description": "Target IP range (CIDR)"}, {"name": "ports", "label": "Ports", "type": "text", "required": true, "default": "-p 80,443", "placeholder": "-p 0-65535", "description": "Ports to scan"}, {"name": "rate", "label": "Rate", "type": "text", "required": false, "default": "--rate 1000", "placeholder": "--rate 10000", "description": "Packets per second"}, {"name": "banners", "label": "Banners", "type": "text", "required": false, "default": "", "placeholder": "--banners", "description": "Capture banners (flag value)"}, {"name": "output", "label": "Output File", "type": "text", "required": false, "default": "", "placeholder": "-oL results.txt", "description": "Output to list file"}], "danger_level": "low", "target_types": []}'::jsonb WHERE name='masscan' AND is_active=TRUE;
